#!/usr/bin/env python3
"""Automatic Gazebo startup sequence for the real Noetix control path.

Sequence:
    backend held in air -> enable -> stand -> settle -> instant hoist release.

The manager never publishes LowCmd.  STAND is generated by the existing
noetix_pose_mode_node, exactly as on the real robot.
"""

from __future__ import annotations

from enum import Enum, auto

import rclpy
from rclpy.node import Node
from rclpy.qos import QoSProfile, ReliabilityPolicy, DurabilityPolicy
from std_msgs.msg import String

from noetix_msgs.msg import LowState, RobotStatus


class Phase(Enum):
    WAIT_STATE = auto()
    WAIT_ENABLED = auto()
    WAIT_STAND = auto()
    RELEASED = auto()


class SimStartupManager(Node):
    def __init__(self) -> None:
        super().__init__("noetix_sim_startup_manager")

        self.declare_parameter("auto_stand", True)
        self.declare_parameter("stand_duration_s", 2.0)
        self.declare_parameter("stand_settle_s", 0.5)
        self.declare_parameter("request_retry_s", 0.5)

        self.auto_stand = bool(self.get_parameter("auto_stand").value)
        self.stand_duration_s = float(
            self.get_parameter("stand_duration_s").value)
        self.stand_settle_s = float(
            self.get_parameter("stand_settle_s").value)
        self.request_retry_s = float(
            self.get_parameter("request_retry_s").value)

        if self.stand_duration_s <= 0.0:
            raise ValueError("stand_duration_s must be > 0")
        if self.stand_settle_s < 0.0:
            raise ValueError("stand_settle_s must be >= 0")

        self.latest_state: LowState | None = None
        self.phase = Phase.WAIT_STATE
        self.phase_started_ns = self.get_clock().now().nanoseconds
        self.last_request_ns = 0

        reliable = QoSProfile(
            depth=10,
            reliability=ReliabilityPolicy.RELIABLE,
        )
        latched = QoSProfile(
            depth=1,
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.TRANSIENT_LOCAL,
        )

        self.request_pub = self.create_publisher(
            String, "/noetix/control_request", reliable)
        self.hoist_pub = self.create_publisher(
            String, "/noetix/sim/hoist_request", latched)
        self.state_sub = self.create_subscription(
            LowState, "/noetix/low_state", self._on_state, reliable)

        # Use the node clock. sim.launch.py sets use_sim_time=true, therefore
        # the sequence follows Gazebo simulation time instead of wall time.
        self.timer = self.create_timer(0.02, self._step)

        self.get_logger().info(
            "Simulation startup manager ready: "
            f"auto_stand={self.auto_stand} "
            f"stand={self.stand_duration_s:.3f}s "
            f"settle={self.stand_settle_s:.3f}s")

    def _on_state(self, msg: LowState) -> None:
        self.latest_state = msg

    def _now_s(self) -> float:
        return self.get_clock().now().nanoseconds * 1.0e-9

    def _phase_elapsed(self) -> float:
        return (
            self.get_clock().now().nanoseconds - self.phase_started_ns
        ) * 1.0e-9

    def _set_phase(self, phase: Phase) -> None:
        self.phase = phase
        self.phase_started_ns = self.get_clock().now().nanoseconds
        self.last_request_ns = 0

    def _publish_string(self, pub, text: str) -> None:
        msg = String()
        msg.data = text
        pub.publish(msg)

    def _request(self, text: str) -> None:
        self._publish_string(self.request_pub, text)
        self.last_request_ns = self.get_clock().now().nanoseconds
        self.get_logger().info(f"control_request -> {text}")

    def _retry_due(self) -> bool:
        if self.last_request_ns == 0:
            return True
        elapsed = (
            self.get_clock().now().nanoseconds - self.last_request_ns
        ) * 1.0e-9
        return elapsed >= self.request_retry_s

    def _step(self) -> None:
        if not self.auto_stand or self.phase == Phase.RELEASED:
            return

        state = self.latest_state
        if state is None or not state.status.connected:
            return

        if self.phase == Phase.WAIT_STATE:
            self._set_phase(Phase.WAIT_ENABLED)
            if state.status.mode == RobotStatus.MODE_DISABLED:
                self._request("enable")
                return

        if self.phase == Phase.WAIT_ENABLED:
            if state.status.mode != RobotStatus.MODE_ENABLED:
                if self._retry_due():
                    self._request("enable")
                return

            self._request("stand")
            self._set_phase(Phase.WAIT_STAND)
            self.get_logger().info(
                "Robot remains suspended while the existing STAND controller "
                "moves all joints to the configured pose")
            return

        if self.phase == Phase.WAIT_STAND:
            if state.status.mode != RobotStatus.MODE_ENABLED:
                self.get_logger().warning(
                    "Drive became disabled before hoist release; startup reset")
                self._set_phase(Phase.WAIT_STATE)
                return

            required = self.stand_duration_s + self.stand_settle_s
            if self._phase_elapsed() < required:
                return

            self._publish_string(self.hoist_pub, "release")
            self._set_phase(Phase.RELEASED)
            self.get_logger().warning(
                "Virtual hoist RELEASED: base_link is now fully dynamic; "
                "the robot will free-fall the configured small clearance "
                "under Gazebo gravity")


def main(args=None) -> None:
    rclpy.init(args=args)
    node = SimStartupManager()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == "__main__":
    main()
